const key = f => f + '?h=' + (HASH[f] || VERSION);
// Мимо кэша: ИИ и LanguageTool (живые запросы), карточки главного, книга автора (личный экземпляр, не кэшируем).
const BYPASS = [/^\/ollama\//, /^\/lt\//, /^\/asr\//, /^\/phon\//, /^\/books\//, /^\/cards\//];

async function clean(r) {
  if (!r.redirected) return r;
  return new Response(await r.blob(), { status: r.status, statusText: r.statusText, headers: r.headers });
}

self.addEventListener('install', e => {
  e.waitUntil((async () => {
    const c = await caches.open(CACHE);
    const have = new Set((await c.keys()).map(r => { const u = new URL(r.url); return u.pathname + u.search; }));
    const todo = FILES.filter(f => !have.has(SCOPE + key(f)));
    let done = FILES.length - todo.length;
    const report = async () => {
      for (const cl of await self.clients.matchAll({ includeUncontrolled: true }))
        cl.postMessage({ type: 'progress', done, total: FILES.length });
    };
    for (let i = 0; i < todo.length; i += 6) {
      await Promise.all(todo.slice(i, i + 6).map(async f => {
        const old = await caches.match(key(f)); // тот же файл с тем же хэшем уже есть в старом кэше — без сети
        if (old) { await c.put(key(f), old); done++; return; }
        let r = await fetch(new Request(f, { cache: 'reload' }));
        if (!r.ok) throw new Error(f + ' ' + r.status);
        await c.put(key(f), await clean(r));
        done++;
      }));
      if (i % 30 === 0) report();
    }
    await report();
  })());
});

self.addEventListener('activate', e => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith(PREFIX) && k !== CACHE && k.endsWith(':' + SCOPE)) await caches.delete(k);
    await self.clients.claim();
  })());
});

self.addEventListener('message', e => {
  if (!e.data) return;
  if (e.data.type === 'skipWaiting') self.skipWaiting();
  if (e.data.type === 'version' && e.ports[0]) e.ports[0].postMessage({ version: VERSION, cache: CACHE });
});

async function ranged(req, res) {
  const range = req.headers.get('range');
  if (!range) return res;
  const m = /bytes=(\d*)-(\d*)/.exec(range);
  const buf = await res.arrayBuffer();
  const size = buf.byteLength;
  let start = m && m[1] !== '' ? +m[1] : 0;
  let end = m && m[2] !== '' ? +m[2] : size - 1;
  if (m && m[1] === '' && m[2] !== '') { start = size - +m[2]; end = size - 1; }
  if (start >= size || start > end) return new Response(null, { status: 416, headers: { 'Content-Range': `bytes */${size}` } });
  end = Math.min(end, size - 1);
  return new Response(buf.slice(start, end + 1), {
    status: 206, statusText: 'Partial Content',
    headers: { 'Content-Type': res.headers.get('Content-Type') || 'application/octet-stream', 'Content-Range': `bytes ${start}-${end}/${size}`, 'Content-Length': String(end - start + 1), 'Accept-Ranges': 'bytes' },
  });
}

self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== location.origin) return;              // YouTube и прочее внешнее — не трогаем
  if (BYPASS.some(rx => rx.test(url.pathname))) return;     // сеть напрямую
  if (!url.pathname.startsWith(SCOPE)) return;
  const rel = url.pathname.slice(SCOPE.length);
  if (rel === 'version.json' || rel === 'sw.js') return;    // всегда из сети (no-store)
  if (rel.startsWith('vendor/')) {                          // ИИ в браузере (25.11): web-llm не в предкэше; после первой загрузки — из своего кэша (версия в имени файла)
    e.respondWith(caches.open('ds-vendor').then(async v => (await v.match(rel)) || fetch(req).then(r => { if (r.ok) v.put(rel, r.clone()); return r; })));
    return;
  }
  const isApp = req.mode === 'navigate' && (rel === '' || rel === 'index.html');
  e.respondWith((async () => {
    const c = await caches.open(CACHE);
    let hit = await c.match(isApp ? 'index.html' : rel, { ignoreSearch: true });
    if (hit) return ranged(req, await clean(hit));
    try { return await fetch(req); }
    catch (err) {
      if (req.mode === 'navigate') { const idx = await c.match('index.html'); if (idx) return clean(idx); }
      return new Response('Нет сети, и этого файла нет в кэше: ' + rel, { status: 504, headers: { 'Content-Type': 'text/plain; charset=utf-8' } });
    }
  })());
});
